mapper.select:
SELECT fix_price.* FROM scc_npm_sou_fix_price_head fix_price WHERE 1 = 1
AND fix_price.FIX_PRICE_NO LIKE concat('%', concat(#{fixPriceNo}, '%'))
AND fix_price.FIX_PRICE_STATUS = #{fixPriceStatus}
AND fix_price.ORG_DEP_NAME LIKE concat('%', concat(#{orgDepName}, '%'))
AND fix_price.CREATION_DATE >= #{creationDateFrom}
AND fix_price.CREATION_DATE <= #{creationDateTo}
AND date(fix_price.CREATION_DATE) = #{creationDate}
AND fix_price.CREATED_BY = #{createdBy}
AND exists ( SELECT fix_line.FIX_PRICE_HEAD_ID from scc_npm_sou_fix_price_line fix_line WHERE fix_line.FIX_PRICE_HEAD_ID = fix_price.FIX_PRICE_HEAD_ID AND fix_line.ITEM_CODE LIKE concat('%', concat(#{itemCode}, '%')) )
AND exists ( SELECT fix_line.FIX_PRICE_HEAD_ID from scc_npm_sou_fix_price_line fix_line WHERE fix_line.FIX_PRICE_HEAD_ID = fix_price.FIX_PRICE_HEAD_ID AND fix_line.ITEM_DESC LIKE concat('%', concat(#{itemDesc}, '%')) )
AND fix_price.FIX_PRICE_HEAD_ID in
#{item}
and EXISTS (select 1 from scc_npm_sou_fix_price_line l where l.VENDOR_NAME like CONCAT('%',#{vendorName},'%') and fix_price.FIX_PRICE_HEAD_ID = l.FIX_PRICE_HEAD_ID limit 1)
and EXISTS(select 1 from scc_npm_sou_fix_price_line l where l.EXT_MATERIAL_MODEL like CONCAT('%',#{extMaterialModel},'%') and fix_price.FIX_PRICE_HEAD_ID = l.FIX_PRICE_HEAD_ID limit 1)
ORDER BY fix_price.FIX_PRICE_NO desc

SELECT DISTINCT i.MATERIAL_CODE materialCode, i.MATERIAL_ID materialId, a.SUPPLY_AREA supplyArea, g.BUY_ORG_CODE buyOrgCode, g.BUY_ORG_NAME buyOrgName from scc_sou_jc_agreement a JOIN scc_sou_jc_agreement_info i on i.AGREEMENT_ID = a.AGREEMENT_ID JOIN scc_sou_jc_agreement_org g on g.AGREEMENT_ID = a.AGREEMENT_ID
where a.AGREEMENT_STATUS='EXECUTING' and i.MATERIAL_ID IN
#{item}
and g.BUY_ORG_CODE IN
#{item}
and a.SUPPLY_AREA IN
#{item}
